<?php
namespace App\Http\Requests\Organization;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class StoreInitiativeRequest extends FormRequest { public function authorize():bool{return $this->user()?->hasPermission('program.manage')??false;} public function rules():array{return ['type'=>['required',Rule::in(config('organization.initiative_types'))],'title'=>['required','string','max:255'],'summary'=>['nullable','string','max:5000'],'status'=>['nullable',Rule::in(config('organization.initiative_statuses'))],'starts_on'=>['nullable','date'],'ends_on'=>['nullable','date','after_or_equal:starts_on'],'lead_committee'=>['nullable','string','max:255'],'owner_user_id'=>['nullable','uuid','exists:users,id'],'budget_total'=>['nullable','numeric','min:0'],'budget_currency'=>['nullable','string','size:3'],'visibility'=>['nullable',Rule::in(['internal','members','public'])],'audience_filters'=>['nullable','array'],'outcome_summary'=>['nullable','string','max:10000']];} }
